using AuthService.Application.Features.Authentication.Login; namespace AuthService.Api.Features.Authentication; public static class AuthEndpoints { public static void MapAuthEndpoints(this IEndpointRouteBuilder app){app.MapPost("/api/auth/login",async (LoginRequest r,LoginHandler h,CancellationToken ct)=>{var o=await h.HandleAsync(r,ct);return o.Kind switch {LoginOutcomeKind.Success=>Results.Ok(o.Response),LoginOutcomeKind.ValidationFailure=>Results.ValidationProblem(new Dictionary<string,string[]>{{"credentials",["Invalid credentials."]}}),_=>Results.Problem(statusCode:401,title:"Invalid credentials")};}).AllowAnonymous();} }
